type agreementTreeDiscardedCodeDiagnosticSingle struct {
	Field, Index, Start int
	Body                string
	Diagnostics         []render.Diagnostic
}
type agreementTreeDiscardedCodeDiagnosticWitness struct {
	Name, Body, Target, Selected    string
	Diagnostics, PrivateDiagnostics []render.Diagnostic
	Indices                         []int
	Singles                         []agreementTreeDiscardedCodeDiagnosticSingle
}

type agreementTreeDiscardedCodeDiagnosticOwner struct {
	Field, Declaration, Root, Node int
	Label                          string
	Bounds                         agreementNativeDefinitionSpan
}

func agreementTreeDiscardedCodeDiagnosticOwners(check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree, target string) ([]agreementTreeDiscardedCodeDiagnosticOwner, bool) {
	if !tree.Valid || target == "" {
		return nil, false
	}
	var owners []agreementTreeDiscardedCodeDiagnosticOwner
	used := map[graph.Span]bool{}
	for fi, f := range check.Fields {
		if !f.Code || f.Comment || f.Escaped || f.DefinitionOwner >= 0 || !slices.Contains(f.Targets, target) {
			continue
		}
		if len(f.Targets) != 1 || used[f.Span] {
			return nil, false
		}
		at := -1
		for di, d := range tree.Definitions {
			if !d.Found || d.Node != 0 || d.Root < 1 || d.Root >= len(tree.Trees) || len(tree.Trees[d.Root]) == 0 || tree.Trees[d.Root][0].Kind != extast.KindFootnote.String() || d.Label == "" || d.Bounds.Parent == "" || d.Bounds.Span.Start < 0 || d.Bounds.Span.Stop <= d.Bounds.Span.Start || d.Bounds.Label.Start < d.Bounds.Span.Start || d.Bounds.Label.Stop > d.Bounds.Span.Stop || d.Bounds.Label.Stop <= d.Bounds.Label.Start || f.Span.Start < d.Bounds.Span.Start || f.Span.Stop > d.Bounds.Span.Stop || f.Span.Stop <= f.Span.Start {
				continue
			}
			if at >= 0 {
				return nil, false
			}
			at = di
		}
		if at < 0 {
			continue
		}
		d := tree.Definitions[at]
		used[f.Span] = true
		owners = append(owners, agreementTreeDiscardedCodeDiagnosticOwner{fi, at, d.Root, d.Node, d.Label, d.Bounds})
	}
	return owners, len(owners) > 0
}
func agreementTreeDiscardedCodeDiagnosticPrivate(body, target string, check *agreementNativeCheckSource, tree *agreementNativeProseAddressTree) (string, []agreementMixedRename, bool) {
	owners, ok := agreementTreeDiscardedCodeDiagnosticOwners(check, tree, target)
	if !ok || strings.Contains(body, "q") {
		return "", nil, false
	}
	private := []byte(body)
	var changes []agreementMixedRename
	for _, owner := range owners {
		f := check.Fields[owner.Field]
		if f.Span.Start < 0 || f.Span.Stop > len(body) || owner.Bounds.Span.Stop > len(body) || body[f.Span.Start:f.Span.Stop] != f.Word || !strings.HasPrefix(f.Word, "[[") || !strings.HasSuffix(f.Word, "]]") {
			return "", nil, false
		}
		inner := f.Word[2 : len(f.Word)-2]
		link, valid := graph.ParseWikilink(inner)
		if !valid || link.Target != target || strings.ContainsAny(inner, "[]\r\n") || strings.ContainsRune(inner, 96) {
			return "", nil, false
		}
		start := f.Span.Start + 2 + strings.Index(inner, target)
		stop := start + len(target)
		if start < f.Span.Start+2 || stop > f.Span.Stop-2 || body[start:stop] != target {
			return "", nil, false
		}
		replacement := strings.Repeat("q", len(target))
		copy(private[start:stop], replacement)
		changes = append(changes, agreementMixedRename{Field: owner.Field, Span: graph.Span{Start: start, Stop: stop}, Old: target, New: replacement})
	}
	return string(private), changes, true
}

func agreementTreeDiscardedCodeDiagnosticSource(body, target string) (*agreementTreeDiscardedCodeDiagnosticSourceWitness, *agreementTreeDiscardedCodeDiagnosticVariant, bool) {
	witnesses := agreementTreeDiscardedCodeDiagnosticSources()
	for wi := range witnesses {
		w := &witnesses[wi]
		if w.Body != body {
			continue
		}
		for vi := range w.Variants {
			v := &w.Variants[vi]
			if v.Target == target {
				return w, v, true
			}
		}
		return nil, nil, false
	}
	return nil, nil, false
}

// Every changed diagnostic belongs to one declared discarded field.
func agreementTreeDiscardedCodeDiagnosticDifference(c agreementCase, f *agreementFailure, raw string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P0" || f.Identity != "diagnostic-html" || f.Direction != "diagnostic-only" || f.Multiplicity < 1 || f.Tuple.SourceRole != "" || f.Tuple.State != "wikilink-broken" || f.Tuple.Section != "" || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound {
		return "", "", ""
	}
	records := agreementTreeDiscardedCodeDiagnosticWitnesses()
	for ri := range records {
		r := &records[ri]
		if c.Body != r.Body || f.Tuple.Target != r.Target {
			continue
		}
		if agreementSignature(f) != r.Selected || !cmp.Equal(diagnostics, r.Diagnostics) {
			return "", "", ""
		}
		w, v, found := agreementTreeDiscardedCodeDiagnosticSource(c.Body, r.Target)
		if !found {
			return "", "", ""
		}
		native := agreementNativeOwnerReading(c.Body)
		check := agreementNativeCheckReading(c.Body, native)
		tree := agreementNativeProseAddressTreeReading(c.Body, nil)
		parts, pok := agreementCodeWindowParts(raw)
		owners, ok := agreementTreeDiscardedCodeDiagnosticOwners(&check, &tree, r.Target)
		private, changes, valid := agreementTreeDiscardedCodeDiagnosticPrivate(c.Body, r.Target, &check, &tree)
		if !pok || !ok || !valid || len(owners) != f.Multiplicity || len(r.Indices) != len(owners) || !cmp.Equal(owners, v.Owners) || !cmp.Equal(changes, v.Changes) || private != v.Body || !cmp.Equal(native, w.Native) || !cmp.Equal(check, w.Check) || !cmp.Equal(tree, w.Tree) || !cmp.Equal(agreementNativeCodePayloadSites(c.Body), w.Sites) || !cmp.Equal(agreementNativeHTMLAddressSites(c.Body), w.HTML) || !cmp.Equal(judge.LinkTargets(c.Body), w.Targets) || !cmp.Equal(parts, w.Parts) || !cmp.Equal(*page, w.Page) || !maps.Equal(agreementMixedCurrent(failures), w.Signatures) {
			return "", "", ""
		}
		return "debt", "#1011 stage 5", "page-diagnostic"
	}
	return "", "", ""
}

